// Obtiene todos los items que llegan desde el nodo anterior
const items = $input.all();

// Si no hay resultados, devuelve una estructura vacía
if (items.length === 0) {
  return {
    json: {
      data: [],
      total: 0
    }
  };
}

// Extrae el conteo total del primer item.
const total = items[0].json.total;

// Prepara el array de datos, quitando el campo 'total' de cada objeto para no ser redundante.
const data = items.map(item => {
  const { total, ...restOfItem } = item.json;
  return restOfItem;
});

return {
  json: {
    data: data,
    total: total
  }
};

// Sanea y normaliza los filtros/orden/paginación que llegan por querystring
// antes de pasarlos como parámetros bindeados a la consulta de audit_log.
const q = $input.first().json.query || {};

// Whitelist de columnas ordenables -> expresión SQL segura (nunca se concatena texto libre del usuario).
const SORT_COLUMNS = {
  changed_at: 't.changed_at',
  table_name: 't.table_name',
  operation: 't.operation',
  changed_by: 'u.name',
  record_id: 't.record_id',
};

const sortKey = SORT_COLUMNS[q.sort_by] ? q.sort_by : 'changed_at';
const orderColumn = SORT_COLUMNS[sortKey];
const orderDirection = String(q.sort_order || '').toUpperCase() === 'ASC' ? 'ASC' : 'DESC';

const limit = Math.min(Math.max(parseInt(q.limit, 10) || 25, 1), 1000);
const page = Math.max(parseInt(q.page, 10) || 1, 1);
const offset = (page - 1) * limit;

return {
  json: {
    tableName: q.table_name || null,
    operation: q.operation || null,
    changedBy: q.changed_by || null,
    dateFrom: q.date_from ? `${q.date_from} 00:00:00` : null,
    dateTo: q.date_to ? `${q.date_to} 23:59:59` : null,
    orderColumn,
    orderDirection,
    limit,
    offset,
  }
};

